    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 80-year-old male named Kenneth has developed severe, irreversible septic shock and multi-organ failure. He is unresponsive. His designated healthcare proxy, his daughter, is asked whether to initiate hemodialysis. The proxy states: ''We never discussed kidney failure or dialysis, but I know how much he loved his independence and always said he would never want to live in a vegetative state or dependent on machines. Based on that, I know he would say no to dialysis.'' Which ethical decision-making standard is the proxy applying?', '["Substituted judgment; where the surrogate makes the decision they believe the patient would have made for themselves based on the patient''s known values, goals, and prior statements", "Autologous proxy standard; where the physician makes the decision and the surrogate simply signs the consent form", "Therapeutic privilege; where the surrogate defers all decision-making to the medical team''s personal values", "Distributive justice; where treatment is withheld based on the financial cost to the hospital and society", "Best interest standard; where the surrogate chooses the option that a reasonable person would select to maximize objective clinical benefit"]'::jsonb, 0, 'The **substituted judgment standard** is the primary ethical standard used by surrogate decision-makers when a patient lacks capacity but has left some indication of their values or preferences. Under this standard, the surrogate does not choose what they personally want, nor what they think is best for the patient; instead, they **step into the patient''s shoes** and make the decision that the **patient would make for themselves** based on their known personality, lifestyle, values, religious beliefs, and previous statements. (Ref: UWorld Step 2 CK; First Aid Step 2 CK)'),
